selected.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [x['id'] for x in group]
        if valid(ids):
            ordered = sorted(group, key=lambda x: (x['rank'], x['id']))
            result = [x['id'] for x in ordered]
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
    if valid(selection):
        result = selection
    else:
        result = []
if not exists('/output/selection'):
    if result and valid(result):
        write('/output/selection', result)
        selection = result
    else:
        selection = []
if selection and valid(selection):
    receipt_state = receipt('report')
    if receipt_state == 'unattempted':
        send('report', 'team', selection)
    elif receipt_state == 'unknown':
        delivery_state = status('report')
        if delivery_state == 'not_sent':
            send('report', 'team', selection)
elif receipt('report') == 'unknown':
    status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')
